problems.solution:
import math

def gaussian_nll(data, mu, sigma):
    return sum(math.log(sigma * math.sqrt(2 * math.pi)) + (x - mu) ** 2 / (2 * sigma ** 2) for x in data)

def gaussian_mle(data):
    n = len(data)
    mu = sum(data) / n
    var = sum((x - mu) ** 2 for x in data) / n
    return mu, math.sqrt(var)
